const DEFAULTS={working_days:'26',hours_per_day:'8',ot_multiplier:'1.5',tax_slabs:'0:0\n600000:1\n1200000:11\n2200000:23\n3200000:30\n4100000:35',surcharge_threshold:'10000000',surcharge_rate:'9'};
const setting=k=>get('select value from settings where key=?',[k])?.value??DEFAULTS[k];const num=k=>+setting(k)||0;
const ATT=['present','absent','leave','unpaid leave','half-day','late'],ABBR={present:'P',absent:'A',leave:'L','unpaid leave':'UL','half-day':'H',late:'Lt'};
function slabs(){return setting('tax_slabs').split(/\n/).map(l=>l.split(':').map(Number)).filter(a=>a.length===2&&!isNaN(a[0])&&!isNaN(a[1])).sort((a,b)=>a[0]-b[0])}
function annualTax(inc){const sl=slabs();let t=0;sl.forEach(([from,rate],i)=>{const to=sl[i+1]?sl[i+1][0]:Infinity;if(inc>from)t+=(Math.min(inc,to)-from)*rate/100});if(inc>num('surcharge_threshold'))t*=1+num('surcharge_rate')/100;return t}
function calc(p,taxOn){const gross=p.basic-p.absence_deduction+p.allowances+p.ot_pay;const tax=taxOn?Math.round(annualTax(Math.max(0,gross)*12)/12):0;return{gross:Math.round(gross),tax,net:Math.round(gross-tax-p.deductions)}}
