function balances(eid,year){return all("select t.*,coalesce((select sum(days) from requests r where r.employee_id=? and r.kind='leave' and r.leave_type_id=t.id and r.status='approved' and substr(r.start_date,1,4)=?),0) used,coalesce((select sum(days) from requests r where r.employee_id=? and r.kind='leave' and r.leave_type_id=t.id and r.status like 'pending%' and substr(r.start_date,1,4)=?),0) pending from leave_types t order by t.id",[eid,String(year),eid,String(year)])}
const RSTAT={pending_tl:'Pending team lead',pending_hr:'Pending HR',approved:'Approved',rejected:'Rejected'};
const stTag=s=>`<span class="tag ${s==='rejected'?'rejected':s==='approved'?'':'training'}">${RSTAT[s]||s}</span>`;
function applyApproved(r){if(r.kind==='leave'){const lt=get('select * from leave_types where id=?',[r.leave_type_id]);for(let d=new Date(r.start_date);d<=new Date(r.end_date);d.setDate(d.getDate()+1)){if(d.getDay()===0)continue;const ds=d.toISOString().slice(0,10);const st=lt.paid?'leave':(r.half_day?'half-day':'unpaid leave');
  run("insert into attendance(employee_id,date,status,check_in,check_out,ot_hours) values(?,?,?,'','',0) on conflict(employee_id,date) do update set status=excluded.status",[r.employee_id,ds,st])}}
 else run("insert into attendance(employee_id,date,status,check_in,check_out,ot_hours) values(?,?,'present','','',?) on conflict(employee_id,date) do update set ot_hours=coalesce(ot_hours,0)+excluded.ot_hours",[r.employee_id,r.start_date,r.hours])}
