 db.run("create table if not exists attendance(id integer primary key,employee_id integer,date text,status text,check_in text,check_out text,ot_hours real default 0,unique(employee_id,date))");
 const cols=t=>all('pragma table_info('+t+')').map(c=>c.name);
 if(!cols('employees').includes('tax_enabled'))db.run('alter table employees add column tax_enabled integer default 1');
 [['gross','real default 0'],['unpaid_days','real default 0'],['absence_deduction','real default 0'],['ot_hours','real default 0'],['ot_pay','real default 0'],['tax','real default 0'],['days_present','real default 0']].forEach(([c,t])=>{if(!cols('payslips').includes(c))db.run('alter table payslips add column '+c+' '+t)});
 Object.entries(DEFAULTS).forEach(([k,v])=>db.run('insert or ignore into settings values(?,?)',[k,v]));
