  E.forEach(e=>db.run("insert into employees(name,email,position,department,status,hire_date,base_salary,training_rate,allowance,deduction) values(?,?,?,'Operations',?,?,?,?,?,?)",[e[0],e[0].split(' ')[0].toLowerCase()+'@revupglobal.com',e[1],e[2],e[3],e[4],e[5],e[6],e[7]]));
  for(let d=1;d<=9;d++){const dt='2026-10-'+String(d).padStart(2,'0');if(new Date(dt).getDay()===0)continue;for(let e=1;e<=5;e++){let st='present',ot=0;if(e===1&&d===6)st='absent';if(e===2&&d===7)st='half-day';if(e===4&&d===8)st='late';if(e===5&&d===2)st='leave';if(e===3&&d%2)ot=2;db.run("insert into attendance(employee_id,date,status,check_in,check_out,ot_hours) values(?,?,?,?,?,?)",[e,dt,st,st==='late'?'09:40':'09:00',e===3&&d%2?'19:00':'17:00',ot])}}
