// CSRF: per-session token, injected into every POST form, checked on every POST
app.use((req,res,next)=>{if(!req.session.csrf)req.session.csrf=crypto.randomBytes(24).toString('hex');const tok=req.session.csrf,send=res.send.bind(res);
 res.send=b=>send(typeof b==='string'?b.replace(/<form([^>]*method=post[^>]*)>/gi,m=>m+`<input type=hidden name=_csrf value="${tok}">`):b);
 if(req.method==='POST'&&req.body?._csrf!==tok)return res.status(403).send('Invalid or expired form token. Go back, refresh the page and try again.');next()});
const auth=(req,res,next)=>req.session.user?next():res.redirect('/login');
const admin=(req,res,next)=>req.session.user?.role==='admin'?next():res.status(403).send(page(req,'Forbidden','<div class=card>Admins only.</div>'));
const CSS=`:root{--g:#3A6B60;--m:#84C3A7;--l:#eef7f2}*{box-sizing:border-box}body{margin:0;font-family:system-ui,Segoe UI,Arial;background:var(--l);color:#1d2b27}
header{background:var(--g);color:#fff;display:flex;align-items:center;gap:18px;padding:10px 24px}header img{height:40px;background:#fff;border-radius:6px;padding:3px}header b{font-size:18px}
nav{display:flex;gap:4px;flex-wrap:wrap;flex:1}nav a{color:#fff;text-decoration:none;padding:8px 12px;border-radius:6px}nav a:hover,nav a.on{background:var(--m);color:#14302a}
main{padding:24px;max-width:1200px;margin:auto}.card{background:#fff;border-radius:10px;padding:18px;margin-bottom:18px;box-shadow:0 1px 3px #0002;border-top:4px solid var(--m)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}.stat{font-size:30px;font-weight:700;color:var(--g)}
table{width:100%;border-collapse:collapse}th{background:var(--g);color:#fff;text-align:left}th,td{padding:8px;border-bottom:1px solid #dde}tr:nth-child(even) td{background:#f6fbf8}
input,select,textarea{padding:7px;border:1px solid #bcd;border-radius:6px;width:100%}label{font-size:13px;color:#456;display:block;margin-top:6px}
.btn,button{background:var(--g);color:#fff;border:0;padding:8px 14px;border-radius:6px;cursor:pointer;text-decoration:none;display:inline-block;font-size:14px}.btn.m{background:var(--m);color:#14302a}.btn.r{background:#b04a4a}
.f{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;align-items:end}.tag{padding:2px 8px;border-radius:10px;background:var(--m);color:#14302a;font-size:12px}.tag.training{background:#f4d58d}.tag.rejected,.tag.terminated,.tag.failed{background:#e8a4a4}
.kan{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.col{background:#fff;border-radius:8px;padding:8px;min-height:120px}.col h4{margin:4px;color:var(--g);text-transform:capitalize}.ci{background:var(--l);border-left:4px solid var(--m);padding:8px;margin:6px 0;border-radius:4px;font-size:13px}
.bar{background:#dde;border-radius:6px;height:10px}.bar i{display:block;height:10px;background:var(--m);border-radius:6px}
@media print{header,.noprint{display:none}body{background:#fff}}`;
function page(req,title,body){const u=req.session.user,p=req.path;const pend=u?(u.role==='teamlead'?get("select count(*) c from requests r join employees e on e.id=r.employee_id where r.status='pending_tl' and e.team_lead_id=?",[u.employee_id]).c:isStaff(u)?get("select count(*) c from requests where status='pending_hr'").c:0):0;const ap=['/approvals','Approvals'+(pend?` (${pend})`:'')];
const L=u?.role==='employee'?[['/me','My portal'],['/requests','My requests']]:u?.role==='teamlead'?[['/me','My portal'],['/requests','My requests'],['/employees','My team'],['/attendance','Attendance'],ap]:[['/','Dashboard'],['/employees','Employees'],['/hiring','Hiring'],['/training','Training'],['/attendance','Attendance'],ap,...(u?.role==='admin'?[['/payroll','Payroll'],['/settings','Settings']]:[])];
return `<!doctype html><html><head><meta charset=utf-8><title>${esc(title)} · RevUp Global HRM</title><link rel=icon href=/public/logo.png><style>${CSS}</style></head><body>
<header><img src=/public/logo.png alt="RevUp Global"><b>RevUp Global HRM</b><nav>${L.map(([h,t])=>`<a href="${h}" class="${(h==='/'?p==='/':p.startsWith(h))?'on':''}">${t}</a>`).join('')}</nav><span>${esc(u?.name)} (${roleName[u?.role]||''}) · <a style=color:#fff href=/change-password>Password</a> · <a style=color:#fff href=/logout>Logout</a></span></header><main><h2 style="color:#3A6B60">${esc(title)}</h2>${body}</main></body></html>`}
const sel=(n,opts,v)=>`<select name=${n}>${opts.map(o=>`<option ${o==v?'selected':''}>${o}</option>`).join('')}</select>`;
