app.get('/login',(req,res)=>res.send(`<!doctype html><html><head><title>Login · RevUp Global HRM</title><link rel=icon href=/public/logo.png><style>${CSS}body{display:grid;place-items:center;min-height:100vh;background:linear-gradient(135deg,#3A6B60,#84C3A7)}</style></head><body>
<form method=post class=card style="width:340px;text-align:center"><img src=/public/logo.png style="max-width:200px"><h2 style=color:#3A6B60>RevUp Global HRM</h2>${req.query.e?'<p style=color:#b04a4a>Invalid username or password</p>':''}
<input name=username placeholder=Username required><br><br><input name=password type=password placeholder=Password required><br><br><button style=width:100%>Sign in</button></form></body></html>`));
const loginLimiter=rateLimit({windowMs:15*60e3,limit:10,standardHeaders:'draft-7',legacyHeaders:false,handler:(req,res)=>res.status(429).send('Too many login attempts. Try again in 15 minutes.')});
app.post('/login',loginLimiter,(req,res)=>{const u=get('select * from users where username=?',[req.body.username]);if(u&&bcrypt.compareSync(req.body.password||'',u.password_hash)){return req.session.regenerate(()=>{req.session.user={id:u.id,name:u.name,role:u.role,username:u.username,employee_id:u.employee_id,must_change:!!u.must_change};res.redirect('/')})}res.redirect('/login?e=1')});
app.get('/logout',(req,res)=>req.session.destroy(()=>res.redirect('/login')));
app.use(auth);
app.use((req,res,next)=>{if(!req.session.user.must_change||['/change-password','/logout'].includes(req.path))return next();res.redirect('/change-password')});
app.get('/change-password',(req,res)=>res.send(page(req,'Set a new password',`<div class=card style=max-width:420px>${req.session.user.must_change?'<p>Your account has a temporary password. Please choose a new one to continue.</p>':''}${req.query.e?`<p style=color:#b04a4a>${esc(req.query.e)}</p>`:''}<form method=post><label>Current password</label><input type=password name=current required><label>New password (min 8 chars, letters and numbers)</label><input type=password name=password required minlength=8><label>Confirm new password</label><input type=password name=confirm required><br><br><button>Save password</button></form></div>`)));
app.post('/change-password',(req,res)=>{const u=get('select * from users where id=?',[req.session.user.id]),b=req.body,e=m=>res.redirect('/change-password?e='+encodeURIComponent(m));
 if(!bcrypt.compareSync(b.current||'',u.password_hash))return e('Current password is incorrect');if(b.password!==b.confirm)return e('New passwords do not match');if(!(b.password.length>=8&&/[A-Za-z]/.test(b.password)&&/\d/.test(b.password)))return e('Use at least 8 characters with letters and numbers');if(b.password===b.current)return e('New password must be different');
 run('update users set password_hash=?,must_change=0 where id=?',[bcrypt.hashSync(b.password,10),u.id]);req.session.user.must_change=false;res.redirect('/')});
const ALLOW={employee:['/me','/requests','/payslips/','/password','/change-password','/logout'],teamlead:['/me','/requests','/payslips/','/password','/change-password','/logout','/employees','/attendance','/approvals']};
app.use((req,res,next)=>{const r=req.session.user.role;if(!ALLOW[r])return next();if(req.path==='/')return res.redirect('/me');if(ALLOW[r].some(p=>req.path===p||req.path.startsWith(p.endsWith('/')?p:p+'/')))return next();res.status(403).send(page(req,'Forbidden','<div class=card>You do not have access to this page.</div>'))});
